import React, { useEffect, useState } from "react";
import MenuCard from "./MenuCard";

const MenuGrid = () => {
  const [menuItems, setMenuItems] = useState([]);
  const [selectedCollege, setSelectedCollege] = useState("ALL");

  // Fetch menu items
  useEffect(() => {
    fetch("http://127.0.0.1:8000/menu/")
      .then((res) => res.json())
      .then((data) => setMenuItems(data))
      .catch((err) => console.error("Menu fetch error:", err));
  }, []);

  /**
   * ✅ Extract REGISTERED college names
   * - Keep original casing for display
   * - Remove duplicates safely
   */
  const colleges = [
    "ALL",
    ...Array.from(
      new Map(
        menuItems
          .filter((item) => item.college)
          .map((item) => [
            item.college.toLowerCase().trim(), // key (normalized)
            item.college.trim(),               // value (original)
          ])
      ).values()
    ),
  ];

  /**
   * ✅ Filter menu based on selected college
   * - Case-insensitive comparison
   */
  const filteredMenu =
    selectedCollege === "ALL"
      ? menuItems
      : menuItems.filter(
          (item) =>
            item.college &&
            item.college.toLowerCase().trim() ===
              selectedCollege.toLowerCase().trim()
        );

  return (
    <div className="menu-container">
      {/* 🔽 College Dropdown */}
      <div style={{ textAlign: "center", marginBottom: "20px" }}>
        <select
          value={selectedCollege}
          onChange={(e) => setSelectedCollege(e.target.value)}
          style={{
            padding: "10px 16px",
            fontSize: "16px",
            borderRadius: "6px",
            border: "1px solid #ccc",
            minWidth: "220px",
          }}
        >
          {colleges.map((college, index) => (
            <option key={index} value={college}>
              {college === "ALL" ? "All Colleges" : college}
            </option>
          ))}
        </select>
      </div>

      {/* 🧾 Menu Items */}
      <div className="menu-grid">
        {filteredMenu.length > 0 ? (
          filteredMenu.map((item) => (
            <MenuCard key={item.id} item={item} />
          ))
        ) : (
          <p style={{ textAlign: "center", marginTop: "30px" }}>
            No items available for this college
          </p>
        )}
      </div>
    </div>
  );
};

export default MenuGrid;
